// redactCategoryFilter returns a copy of f with the access-redacted
// comparators cleared, for publication as Event.Input on the *Where delete /
// restore ops. nil passes through so a failed upstream
// type assertion publishes nil rather than leaking the raw filter.
//
// Unlike the input helpers this cannot be a shallow copy — a filter is a graph.
// And / Or hold the same filter type, so a nested member would otherwise carry
// a restricted value straight past the top-level clearing, and a relationship
// member can reach another table's redacted columns. Every level returns a new
// value, so the caller's filter is never mutated.
func redactCategoryFilter(f *CategoryFilter) *CategoryFilter {
	if f == nil {
		return nil
	}
	out := *f
	out.Users = redactUserFilter(out.Users)
	if len(out.And) > 0 {
		and := make([]*CategoryFilter, len(out.And))
		for i, sub := range out.And {
			and[i] = redactCategoryFilter(sub)
		}
		out.And = and
	}
	if len(out.Or) > 0 {
		or := make([]*CategoryFilter, len(out.Or))
		for i, sub := range out.Or {
			or[i] = redactCategoryFilter(sub)
		}
		out.Or = or
	}
	return &out
}

// redactUserFilter returns a copy of f with the access-redacted
// comparators cleared, for publication as Event.Input on the *Where delete /
// restore ops. nil passes through so a failed upstream
// type assertion publishes nil rather than leaking the raw filter.
//
// Unlike the input helpers this cannot be a shallow copy — a filter is a graph.
// And / Or hold the same filter type, so a nested member would otherwise carry
// a restricted value straight past the top-level clearing, and a relationship
// member can reach another table's redacted columns. Every level returns a new
// value, so the caller's filter is never mutated.
func redactUserFilter(f *UserFilter) *UserFilter {
	if f == nil {
		return nil
	}
	out := *f
	out.NewPassword = nil
	out.PasswordHash = nil
	out.Categories = redactCategoryFilter(out.Categories)
	if len(out.And) > 0 {
		and := make([]*UserFilter, len(out.And))
		for i, sub := range out.And {
			and[i] = redactUserFilter(sub)
		}
		out.And = and
	}
	if len(out.Or) > 0 {
		or := make([]*UserFilter, len(out.Or))
		for i, sub := range out.Or {
			or[i] = redactUserFilter(sub)
		}
		out.Or = or
	}
	return &out
}

// buildEventHooks creates per-entity event hooks scoped via hook.ForTable.
func buildEventHooks(publisher event.Publisher, cfg event.Config) []hook.MutationHook {
	onError := cfg.ResolveOnError()
	metaFunc := cfg.MetadataFunc
	return []hook.MutationHook{
		hook.ForTable(newAssetEventHook(publisher, onError, metaFunc), TableAssets),
		hook.ForTable(newAssetDocumentLinkEventHook(publisher, onError, metaFunc), TableAssetDocumentLinks),
		hook.ForTable(newCategoryEventHook(publisher, onError, metaFunc), TableCategories),
		hook.ForTable(newDocumentEventHook(publisher, onError, metaFunc), TableDocuments),
		hook.ForTable(newEventEventHook(publisher, onError, metaFunc), TableEvents),
		hook.ForTable(newFilterProbeEventHook(publisher, onError, metaFunc), TableFilterProbes),
		hook.ForTable(newKeyedCodeEventHook(publisher, onError, metaFunc), TableKeyedCodes),
		hook.ForTable(newKeyedCodeEntryEventHook(publisher, onError, metaFunc), TableKeyedCodeEntries),
		hook.ForTable(newMaskedLabelEventHook(publisher, onError, metaFunc), TableMaskedLabels),
		hook.ForTable(newNumericWidthEventHook(publisher, onError, metaFunc), TableNumericWidths),
		hook.ForTable(newOrderEventHook(publisher, onError, metaFunc), TableOrders),
		hook.ForTable(newOrderItemEventHook(publisher, onError, metaFunc), TableOrderItems),
		hook.ForTable(newProductEventHook(publisher, onError, metaFunc), TableProducts),
		hook.ForTable(newProfileEventHook(publisher, onError, metaFunc), TableProfiles),
		hook.ForTable(newScalarProbeEventHook(publisher, onError, metaFunc), TableScalarProbes),
		hook.ForTable(newUserEventHook(publisher, onError, metaFunc), TableUsers),
		hook.ForTable(newUserBadgeEventHook(publisher, onError, metaFunc), TableUserBadges),
		hook.ForTable(newUserCategoryEventHook(publisher, onError, metaFunc), TableUserCategories),
		hook.ForTable(newUserCredentialEventHook(publisher, onError, metaFunc), TableUserCredentials),
		hook.ForTable(newUserSessionEventHook(publisher, onError, metaFunc), TableUserSessions),
		hook.ForTable(newWorkspaceNoteEventHook(publisher, onError, metaFunc), TableWorkspaceNotes),
		hook.ForTable(newWorkspaceSettingEventHook(publisher, onError, metaFunc), TableWorkspaceSettings),
	}
}

// WithEventPublisher configures event publishing for all mutations.
// Event hooks are prepended to the mutation hook chain as the outermost hooks
// (after panic recovery). Events are deferred via Tx.OnCommit inside transactions
// and fire immediately outside transactions. Publish failures invoke OnError but
// never fail the mutation.
func WithEventPublisher(publisher event.Publisher, opts ...func(*event.Config)) ClientOption {
	return func(o *clientOptions) {
		o.eventPublisher = publisher
		for _, opt := range opts {
			opt(&o.eventConfig)
		}
	}
}
